const PART_LABELS = {};

/* rótulos de exibição pra cls — classe gramatical verificada (ver comentário no topo) */
const CLASS_LABELS = {
  verbo: 'Verbo',
  'adj-i': 'Adjetivo-i',
  'adj-na': 'Adjetivo-na',
  substantivo: 'Substantivo',
  numeral: 'Numeral',
  pronome: 'Pronome',
  adverbio: 'Advérbio',
  conjuncao: 'Conjunção',
  interjeicao: 'Interjeição',
  raiz: 'Só em compostos',
};

const G = id => GLYPHS.find(g => g.id === id);
const keyword = id => (G(id)?.kw) || PART_LABELS[id] || id;
const isAtom = g => g.parts.length === 0;

/* níveis presentes, na ordem didática */
const LEVEL_ORDER = ['N5','N4','N3','N2','N1'];
const LEVELS = LEVEL_ORDER.filter(l => GLYPHS.some(g => g.lvl === l));
const glyphsByLevel = lvl => GLYPHS.filter(g => g.lvl === lvl);

/* ordem de ensino: toda peça antes do kanji que a usa */
const TEACH_ORDER = [
  ...GLYPHS.filter(isAtom).map(g=>g.id),
  ...GLYPHS.filter(g=>!isAtom(g)).map(g=>g.id),
];

Object.assign(window, {
  GLYPHS, G, keyword, isAtom, PART_LABELS, CLASS_LABELS,
  TEACH_ORDER, LEVELS, LEVEL_ORDER, glyphsByLevel,
});
